66	@RestController
67	@CrossOrigin(exposedHeaders = "errors, content-type")
68	@RequestMapping("/api")
69	public class OwnerRestControllerV1 implements OwnersApi {
70	
71	    /**
72	     * Matches a syntactically valid email: a non-empty local part and domain separated by a single
73	     * '@', with at least one dot-separated label in the domain and no whitespace anywhere.
74	     */
75	    private static final Pattern EMAIL_PATTERN =
76	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
77	
78	    /**
79	     * Common street-type abbreviations expanded during address normalization, keyed by the
80	     * upper-cased abbreviation.
81	     */
82	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
83	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
84	
85	    /**
86	     * Maximum number of owners a single city may contain. A create is rejected once the owner's
87	     * city already holds this many owners.
88	     */
89	    private static final int CITY_CAPACITY = 50;
90	
91	    /**
92	     * Maximum number of owners that may be created on a single day. A create is rejected once this
93	     * many owners already carry the current day as their {@code registrationDate}.
94	     */
95	    private static final int DAILY_OWNER_LIMIT = 100;
96	
97	    private final ClinicService clinicService;
98	
99	    private final OwnerMapper ownerMapper;
100	
101	    private final PetMapper petMapper;
102	
103	    private final VisitMapper visitMapper;
104	
105	    public OwnerRestControllerV1(ClinicService clinicService,
106	                                 OwnerMapper ownerMapper,
107	                                 PetMapper petMapper,
108	                                 VisitMapper visitMapper) {
109	        this.clinicService = clinicService;
110	        this.ownerMapper = ownerMapper;
111	        this.petMapper = petMapper;
112	        this.visitMapper = visitMapper;
113	    }
114	
115	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
116	    @Override
117	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
118	        Collection<Owner> owners;
119	        if (lastName != null) {
120	            owners = this.clinicService.findOwnerByLastName(lastName);
121	        } else {
122	            owners = this.clinicService.findAllOwners();
123	        }
124	        if (owners.isEmpty()) {
125	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
126	        }
127	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
128	    }
129	
130	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
131	    @Override
132	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
133	        Owner owner = this.clinicService.findOwnerById(ownerId);
134	        if (owner == null) {
135	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
136	        }
137	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
138	    }
139	
140	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
141	    @Override
142	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
143	        validateRequiredFields(ownerFieldsDto);
144	        rejectWhenDailyLimitReached();
145	        HttpHeaders headers = new HttpHeaders();
146	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
147	        owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
148	        rejectWhenCityAtCapacity(owner.getCity());
149	        applyHousehold(owner, ownerFieldsDto.getSharesHousehold());
150	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
151	        rejectDuplicateTelephone(telephone);
152	        owner.setTelephone(telephone);
153	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
154	        if (owner.getRegistrationDate() == null) {
155	            owner.setRegistrationDate(LocalDate.now());
156	        }
157	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
158	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
159	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
160	        this.clinicService.saveOwner(owner);
161	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
162	        headers.setLocation(UriComponentsBuilder.newInstance()
163	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
164	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
165	    }
166	
167	    /**
168	     * Builds the next customer code, formatted {@code <CITY3>-<LAST3>-<NNNN>} where CITY3 is the
169	     * upper-cased first three letters of the owner's city, LAST3 the upper-cased first three letters
170	     * of the owner's last name and NNNN is a per-city 4-digit zero-padded sequence equal to one more
171	     * than the number of owners already in that city (e.g. {@code MAD-SMI-0007}).
172	     *
173	     * @param city     the owner's city
174	     * @param lastName the owner's last name
175	     * @return the assigned customer code
176	     */
177	    private String nextCustomerCode(String city, String lastName) {
178	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
179	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
180	        int sequence = (int) this.clinicService.findAllOwners().stream()
181	            .filter(existing -> equalsIgnoreCase(existing.getCity(), city))
182	            .count() + 1;
183	        return String.format("%s-%s-%04d", city3, last3, sequence);
184	    }
185	
186	    /**
187	     * Builds the owner's membership number, formatted {@code <customerCode>-M<YY>} where YY is the
188	     * last two digits of the registrationDate year, zero-padded (e.g. {@code MAD-SMI-0007-M26}).
189	     *
190	     * @param customerCode     the owner's assigned customer code
191	     * @param registrationDate the owner's registration date
192	     * @return the assigned membership number
193	     */
194	    private String membershipNumber(String customerCode, LocalDate registrationDate) {
195	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
196	    }
197	
198	    /**
199	     * Counts the existing owners that already share the given firstName and lastName, compared
200	     * case-insensitively. Evaluated before the owner being created is saved, so it reflects only
201	     * the owners that pre-existed this create.
202	     *
203	     * @param firstName the new owner's first name
204	     * @param lastName  the new owner's last name
205	     * @return the number of existing namesakes
206	     */
207	    private int countNamesakes(String firstName, String lastName) {
208	        return (int) this.clinicService.findAllOwners().stream()
209	            .filter(existing -> equalsIgnoreCase(existing.getFirstName(), firstName)
210	                && equalsIgnoreCase(existing.getLastName(), lastName))
211	            .count();
212	    }
213	
214	    /**
215	     * Rejects creating an owner when their city already contains {@link #CITY_CAPACITY} or more
216	     * owners. Existing owners are counted case-insensitively by city, matching how the per-city
217	     * customer-code sequence is derived.
218	     *
219	     * @param city the new owner's city
220	     * @throws CityAtCapacityException if the city already holds {@link #CITY_CAPACITY} owners
221	     */
222	    private void rejectWhenCityAtCapacity(String city) {
223	        long count = this.clinicService.findAllOwners().stream()
224	            .filter(existing -> equalsIgnoreCase(existing.getCity(), city))
225	            .count();
226	        if (count >= CITY_CAPACITY) {
227	            throw new CityAtCapacityException(city);
228	        }
229	    }
230	
231	    /**
232	     * Rejects creating an owner once {@link #DAILY_OWNER_LIMIT} or more owners have already been
233	     * created today, counted by their {@code registrationDate}. The current day is taken as
234	     * {@link LocalDate#now()}, matching the default {@code registrationDate} assigned to new owners.
235	     *
236	     * @throws DailyOwnerLimitException if {@link #DAILY_OWNER_LIMIT} owners already carry today's
237	     *                                  registration date
238	     */
239	    private void rejectWhenDailyLimitReached() {
240	        LocalDate today = LocalDate.now();
241	        long count = this.clinicService.findAllOwners().stream()
242	            .filter(existing -> today.equals(existing.getRegistrationDate()))
243	            .count();
244	        if (count >= DAILY_OWNER_LIMIT) {
245	            throw new DailyOwnerLimitException(today);
246	        }
247	    }
248	
249	    private boolean equalsIgnoreCase(String a, String b) {
250	        return a == null ? b == null : a.equalsIgnoreCase(b);
251	    }
252	
253	    /**
254	     * Rejects an owner whose required fields are missing or blank. Collects the names of every
255	     * offending field so the client learns about all of them at once.
256	     *
257	     * @param ownerFieldsDto the submitted owner fields
258	     * @throws MissingOwnerFieldsException if firstName, lastName, address, city or telephone is
259	     *                                     missing or blank
260	     */
261	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
262	        List<String> errors = new ArrayList<>();
263	        if (isBlank(ownerFieldsDto.getFirstName())) {
264	            errors.add("firstName");
265	        }
266	        if (isBlank(ownerFieldsDto.getLastName())) {
267	            errors.add("lastName");
268	        }
269	        if (isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
270	            errors.add("address");
271	        }
272	        if (isBlank(ownerFieldsDto.getCity())) {
273	            errors.add("city");
274	        }
275	        if (isBlank(ownerFieldsDto.getTelephone())) {
276	            errors.add("telephone");
277	        }
278	        if (!errors.isEmpty()) {
279	            throw new MissingOwnerFieldsException(errors);
280	        }
281	    }
282	
283	    private boolean isBlank(String value) {
284	        return value == null || value.isBlank();
285	    }
286	
287	    /**
288	     * Normalizes a submitted telephone into E.164 form. Spaces, dashes and brackets are stripped.
289	     * A leading '+' with its country code is kept; otherwise the country code '+61' is assumed and
290	     * a single leading '0' is dropped from the national digits. The resulting value must be a '+'
291	     * followed by 8 to 15 digits.
292	     *
293	     * @param telephone the raw telephone value as submitted
294	     * @return the E.164 normalized telephone (e.g. {@code +61412345678})
295	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
296	     */
297	    private String normalizeTelephone(String telephone) {
298	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
299	        String nationalSignificantNumber;
300	        if (cleaned.startsWith("+")) {
301	            nationalSignificantNumber = cleaned.substring(1);
302	        } else {
303	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
304	            nationalSignificantNumber = "61" + national;
305	        }
306	        if (!nationalSignificantNumber.matches("[0-9]{8,15}")) {
307	            throw new InvalidTelephoneException(telephone);
308	        }
309	        return "+" + nationalSignificantNumber;
310	    }
311	
312	    /**
313	     * Normalizes a submitted email. An owner may omit the email entirely (a {@code null} or blank
314	     * value is treated as absent and returns {@code null}); when present the value must be a
315	     * syntactically valid address, and is stored and returned lower-cased.
316	     *
317	     * @param email the raw email value as submitted, may be {@code null}
318	     * @return the lower-cased email, or {@code null} when none was supplied
319	     * @throws InvalidEmailException if a non-blank value is not a syntactically valid address
320	     */
321	    private String normalizeEmail(String email) {
322	        if (email == null || email.isBlank()) {
323	            return null;
324	        }
325	        String normalized = email.trim().toLowerCase();
326	        if (!EMAIL_PATTERN.matcher(normalized).matches()) {
327	            throw new InvalidEmailException(email);
328	        }
329	        return normalized;
330	    }
331	
332	    /**
333	     * Rejects a normalized telephone that is already used by any other owner, so telephones stay
334	     * unique across owners. Existing telephones are normalized to E.164 the same way before the
335	     * comparison, so numbers that differ only in formatting still count as duplicates.
336	     *
337	     * @param e164Telephone the E.164 telephone of the owner being created
338	     * @throws DuplicateTelephoneException if another owner already uses the same E.164 telephone
339	     */
340	    private void rejectDuplicateTelephone(String e164Telephone) {
341	        boolean inUse = this.clinicService.findAllOwners().stream()
342	            .map(Owner::getTelephone)
343	            .filter(existing -> existing != null)
344	            .map(this::toComparableTelephone)
345	            .filter(existing -> existing != null)
346	            .anyMatch(e164Telephone::equals);
347	        if (inUse) {
348	            throw new DuplicateTelephoneException(e164Telephone);
349	        }
350	    }
351	
352	    /**
353	     * Normalizes an existing owner's stored telephone to E.164 for duplicate comparison, returning
354	     * {@code null} when it cannot be normalized so a malformed legacy value is simply skipped rather
355	     * than aborting the whole create.
356	     */
357	    private String toComparableTelephone(String telephone) {
358	        try {
359	            return normalizeTelephone(telephone);
360	        } catch (InvalidTelephoneException ex) {
361	            return null;
362	        }
363	    }
364	
365	    /**
366	     * Applies the household rule to an owner being created. An owner belongs to the same household
367	     * as an existing owner when their lastName and address both match (compared case-insensitively
368	     * with runs of whitespace collapsed to a single space).
369	     *
370	     * <p>When no such existing owner exists there is nothing to do. Otherwise the request must
371	     * deliberately opt in to sharing that household by setting {@code sharesHousehold=true}: when it
372	     * does, the new owner and every existing owner in the household are assigned the same stable
373	     * {@link #householdId(String, String) householdId}; when it does not, the create is rejected.
374	     *
375	     * @param owner            the owner being created
376	     * @param sharesHousehold  the request's {@code sharesHousehold} flag, may be {@code null}
377	     * @throws DuplicateHouseholdException if another owner shares the same lastName and address and
378	     *                                     the request did not opt in with {@code sharesHousehold=true}
379	     */
380	    private void applyHousehold(Owner owner, Boolean sharesHousehold) {
381	        String lastNameKey = toHouseholdKey(owner.getLastName());
382	        String addressKey = toHouseholdKey(owner.getAddress());
383	        List<Owner> household = this.clinicService.findAllOwners().stream()
384	            .filter(existing -> toHouseholdKey(existing.getLastName()).equals(lastNameKey)
385	                && toHouseholdKey(existing.getAddress()).equals(addressKey))
386	            .toList();
387	        if (household.isEmpty()) {
388	            return;
389	        }
390	        if (!Boolean.TRUE.equals(sharesHousehold)) {
391	            throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
392	        }
393	        String householdId = householdId(lastNameKey, addressKey);
394	        owner.setHouseholdId(householdId);
395	        for (Owner existing : household) {
396	            if (!householdId.equals(existing.getHouseholdId())) {
397	                existing.setHouseholdId(householdId);
398	                this.clinicService.saveOwner(existing);
399	            }
400	        }
401	    }
402	
403	    /**
404	     * Derives the stable, shared household identifier for a household, formatted {@code HH-<HEX12>}
405	     * where HEX12 is the first 12 upper-cased hex characters of the SHA-256 of the normalized
406	     * lastName and address keys. Being a pure function of the household, every owner in it derives
407	     * the same value regardless of creation order.
408	     *
409	     * @param lastNameKey the normalized household lastName key
410	     * @param addressKey  the normalized household address key
411	     * @return the household identifier
412	     */
413	    private String householdId(String lastNameKey, String addressKey) {
414	        try {
415	            byte[] digest = MessageDigest.getInstance("SHA-256")
416	                .digest((lastNameKey + "|" + addressKey).getBytes(StandardCharsets.UTF_8));
417	            StringBuilder hex = new StringBuilder(digest.length * 2);
418	            for (byte b : digest) {
419	                hex.append(String.format("%02x", b));
420	            }
421	            return "HH-" + hex.substring(0, 12).toUpperCase(Locale.ROOT);
422	        } catch (NoSuchAlgorithmException ex) {
423	            throw new IllegalStateException("SHA-256 not available", ex);
424	        }
425	    }
426	
427	    /**
428	     * Normalizes a lastName or address for household comparison: leading and trailing whitespace is
429	     * trimmed, internal runs of whitespace are collapsed to a single space, and the value is
430	     * lower-cased so the comparison is case-insensitive. A {@code null} value normalizes to an empty
431	     * string.
432	     */
433	    private String toHouseholdKey(String value) {
434	        if (value == null) {
435	            return "";
436	        }
437	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
438	    }
439	
440	    /**
441	     * Normalizes a submitted address into the canonical form stored and returned for an owner:
442	     * leading and trailing whitespace is trimmed, internal runs of whitespace are collapsed to a
443	     * single space, the value is upper-cased, and common street-type abbreviations are expanded on a
444	     * whole-word basis ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}). A {@code null}
445	     * value, or one that is blank once trimmed, normalizes to an empty string.
446	     *
447	     * @param address the raw address value as submitted, may be {@code null}
448	     * @return the normalized address, or an empty string when none was supplied
449	     */
450	    private String normalizeAddress(String address) {
451	        if (address == null) {
452	            return "";
453	        }
454	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
455	        if (collapsed.isEmpty()) {
456	            return "";
457	        }
458	        String[] tokens = collapsed.split(" ");
459	        StringBuilder normalized = new StringBuilder(collapsed.length());
460	        for (int i = 0; i < tokens.length; i++) {
461	            if (i > 0) {
462	                normalized.append(' ');
463	            }
464	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
465	        }
466	        return normalized.toString();
467	    }
