469	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
470	    @Override
471	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
472	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
473	        if (currentOwner == null) {
474	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
475	        }
476	        currentOwner.setAddress(ownerFieldsDto.getAddress());
477	        currentOwner.setCity(ownerFieldsDto.getCity());
478	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
479	        currentOwner.setLastName(ownerFieldsDto.getLastName());
480	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
481	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
482	        this.clinicService.saveOwner(currentOwner);
483	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
484	    }
