498	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
499	    @Override
500	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
501	        Owner owner = this.clinicService.findOwnerById(ownerId);
502	        if (owner == null) {
503	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
504	        }
505	        HttpHeaders headers = new HttpHeaders();
506	        Pet pet = petMapper.toPet(petFieldsDto);
507	        owner.setId(ownerId);
508	        pet.setOwner(owner);
509	        pet.getType().setName(null);
510	        this.clinicService.savePet(pet);
511	        PetDto petDto = petMapper.toPetDto(pet);
512	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
513	            .buildAndExpand(pet.getId()).toUri());
514	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
515	    }
